import sys, json, time
from pathlib import Path
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT=Path('/app/output'); RUNS=Path('/app/runs')
Q=np.array([0.,1.,0.,0.])
SURFACE=.0202
SCALE=.227185/1024

def pose(x,y,z): return np.array([x,y,z,*Q])
def pixel(u,v,z): return pose(.0135925-(v+.5)*SCALE,.1135925-(u+.5)*SCALE,z)

class Painter:
 def __init__(self):
  self.r=Robot(); self.s=self.r.spec();self.k=len(list(RUNS.glob('exec_*')))
 def obs(self,cams=('practice_cam','canvas_cam','scene_cam','side_cam')):
  o=self.r.get_obs(cameras=cams,depth=True);self.save(o,'obs');return o
 def save(self,o,note):
  self.k+=1; d=RUNS/f'exec_{self.k:03d}_{note}';o.save(str(d))
  for cam,im in o.last.items():
   Image.fromarray(im).save(OUT/f'{cam}_latest.png')
   if cam in o.last_depth:np.save(OUT/f'{cam}_depth_latest.npy',o.last_depth[cam])
  print('SAVED',d,'steps',o.meta.get('control_steps'),'tip',o.group('tcp_pose',now=True).round(6).tolist(),flush=True)
 def send(self,rows,note='motion',cams=('practice_cam','scene_cam'),dt=.05):
  rows=np.asarray(rows)
  for j in range(0,len(rows),int(10/dt)):
   a=rows[j:j+int(10/dt)]
   before=self.r.status()
   try:o=self.r.submit('ee_pose',a,dt=dt,cameras=cams,video='none',note=note)
   except Exception:
    after=self.r.wait_ready();print('RECOVERED',before,after,flush=True);raise
   self.save(o,note)
   p=o.meta.get('plan');print('PLAN',p,'stopped',o.stopped,flush=True)
  return o
 def move(self,p,duration=2.,hold=.5,note='move',cams=('practice_cam','scene_cam')):
  cur=self.r.get_obs(cameras=[]).group('tcp_pose',now=True)
  n=max(1,round(duration/.05));rows=np.linspace(cur,p,n+1)[1:]
  rows[:,3:]=Q
  rows=np.vstack([rows,np.tile(p,(round(hold/.05),1))])
  return self.send(rows,note,cams)

if __name__=='__main__':
 p=Painter()
 if sys.argv[1]=='hover':p.move(pose(-.03,-.1856,.08),3,note='practice_hover');p.obs()
